// Function to check if a word is valid
function isValidWord(word) {
    return SCRABBLE_DICTIONARY.has(word.toUpperCase());
}

// Function to get all words of a certain length
function getWordsOfLength(length) {
    return Array.from(SCRABBLE_DICTIONARY).filter(word => word.length === length);
}

// Function to get word count
function getDictionarySize() {
    return SCRABBLE_DICTIONARY.size;
}
